/// Whether one home traps with the code its method trapped with.
fn agrees(trap: Trap) !bool {
    const function = try fixture.runOutcome(t.allocator, trap.function, .{});
    if (!function.trapped()) return false;
    return std.mem.eql(u8, function.trap.code, trap.code);
}

test "W13-S1 a home traps where its method trapped, with the same code" {
    var agreeing: usize = 0;
    for (traps) |trap| agreeing += @intFromBool(try agrees(trap));
    try t.expectEqual(traps.len, agreeing);
}

/// Check `text` as a project's entry module and answer its first error's code, or "" when it checks.
fn firstCode(arena: std.mem.Allocator, text: []const u8) ![]const u8 {
    const report = try fixture.check(arena, text);
    if (report.passed) return "";
    return (report.firstError() orelse return error.TestUnexpectedResult).code;
}

test "W13-S1 a bytes read lends a buffer reached by a name or an element, its literal operand typed as the method's" {
    var arena = std.heap.ArenaAllocator.init(t.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const named = "import buffers\nimport bytes\n\nfunc main() -> int:\n    mut b = buffers.empty()\n    buffers.append(mut b, b\"a,b\")\n    return bytes.find(b, b\",\")\n";
    const element = "import buffers\nimport bytes\n\nfunc main() -> int:\n    mut b = buffers.empty()\n    buffers.append(mut b, b\"a,b\")\n    const held = [b]\n    return bytes.count(held[0], b\",\")\n";
    try t.expectEqualStrings("", try firstCode(a, named));
    try t.expectEqualStrings("", try firstCode(a, element));
}

test "W13-S1 a home is refused in a generic body where its method was, with the same code" {
    var arena = std.heap.ArenaAllocator.init(t.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var agreeing_pins: usize = 0;
    for (generic_pins) |pin| agreeing_pins += @intFromBool(std.mem.eql(u8, try firstCode(a, pin.function), pin.code));
    try t.expectEqual(generic_pins.len, agreeing_pins);
}
